    return mod.default || mod;
  } catch (e) {
    throw e;
  }
})();

const Rgb = RgbModule;

describe('Rgb.reset', () => {
  test('reset sets r, g, b to 255 after modifying values', () => {
    const rgb = new Rgb(10, 20, 30);
    expect(rgb.r).toBe(10);
    expect(rgb.g).toBe(20);
    expect(rgb.b).toBe(30);

    const result = rgb.reset();
    expect(result).toBeUndefined();
    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);
  });

  test('reset is idempotent across multiple resets', () => {
    const rgb = new Rgb(0, 0, 0);
    rgb.reset();
    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);

    // Change values again and reset
    rgb.r = 100;
    rgb.g = 150;
    rgb.b = 200;
    rgb.reset();
    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);
  });

  test('reset on default constructed instance results in 255 values', () => {
    const rgb = new Rgb();
    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);

    const result = rgb.reset();
    expect(result).toBeUndefined();
    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);
  });
});

