'use strict';

const ParticleModule = require('../../../src/core/Particle.js');
const Particle = ParticleModule.default || ParticleModule;

describe('Particle.applyBehaviours', () => {
  test('applies all defined behaviours with correct time and index', () => {
    const particle = new Particle();

    const calls = [];
    const b1 = {
      applyBehaviour: (p, time, index) => {
        calls.push({ behaviour: 'b1', time, index });
        p.p.x = time;
      },
    };
    const b2 = {
      applyBehaviour: (p, time, index) => {
        calls.push({ behaviour: 'b2', time, index });
        p.v.y = index;
      },
    };

    particle.behaviours = [b1, b2];

    particle.applyBehaviours(7, 3);

    expect(particle.p.x).toBe(7);
    expect(particle.v.y).toBe(3);
    expect(calls).toEqual([
      { behaviour: 'b1', time: 7, index: 3 },
      { behaviour: 'b2', time: 7, index: 3 },
    ]);
  });

  test('ignores null/undefined behaviours', () => {
    const particle = new Particle();

    // Ensure initial value can be changed by a valid behaviour
    particle.p.x = 0;

    const validBehaviour = {
      applyBehaviour: (p, time, index) => {
        p.p.x = time;
      },
    };

    particle.behaviours = [null, undefined, validBehaviour];

    particle.applyBehaviours(5, 2);

    expect(particle.p.x).toBe(5);
  });

  test('throws TypeError if a behaviour lacks applyBehaviour or it is not callable', () => {
    const particle = new Particle();

    // A bad behaviour that does not provide a callable applyBehaviour
    particle.behaviours = [{ notApply: 123 }];

    expect(() => particle.applyBehaviours(1, 0)).toThrow(TypeError);
  });
});

