import Particle from '../../../src/core/Particle.js';

describe('Particle.destroy', () => {
  test('should remove all behaviours, zero energy, mark as dead, and clear parent without altering id', () => {
    const p = new Particle({});
    // Setup initial state
    p.energy = 10;
    p.dead = false;
    p.parent = { some: 'object' };
    p.behaviours = ['a', 'b', 'c'];

    const initialId = p.id;

    // Spy on removeAllBehaviours
    const removeSpy = jest.spyOn(p, 'removeAllBehaviours');

    // Invoke destroy
    p.destroy();

    // Assertions
    expect(removeSpy).toHaveBeenCalledTimes(1);
    expect(p.energy).toBe(0);
    expect(p.dead).toBe(true);
    expect(p.parent).toBeNull();
    expect(p.behaviours.length).toBe(0);
    expect(p.id).toBe(initialId);

    // Restore spy
    removeSpy.mockRestore();
  });
});

