describe('EventDispatcher.removeAllEventListeners', () => {
  test('removes all listeners for a specific type', () => {
    const ed = new EventDispatcher();
    ed._listeners = {
      click: ['a', 'b'],
      keydown: ['c']
    };

    ed.removeAllEventListeners('click');
    const listeners = ed._listeners;

    expect(listeners).toBeDefined();

    // Depending on implementation, the 'click' key may be deleted or set to an empty array.
    if (Object.prototype.hasOwnProperty.call(listeners, 'click')) {
      expect(Array.isArray(listeners.click)).toBe(true);
      expect(listeners.click.length).toBe(0);
    } else {
      expect(listeners.click).toBeUndefined();
    }

    // Ensure other listeners remain untouched
    expect(listeners.keydown).toEqual(['c']);
  });

  test('clears all listeners when type is null', () => {
    const ed = new EventDispatcher();
    ed._listeners = {
      a: [1, 2],
      b: [3]
    };

    ed.removeAllEventListeners(null);
    expect(ed._listeners).toBeNull();
  });

  test('does nothing when removing a non-existent type', () => {
    const ed = new EventDispatcher();
    ed._listeners = {
      a: [1],
      b: [2]
    };

    ed.removeAllEventListeners('c');
    expect(ed._listeners).toEqual({
      a: [1],
      b: [2]
    });
  });

  test('does not throw when _listeners is null and a type is provided', () => {
    const ed = new EventDispatcher();
    ed._listeners = null;

    expect(() => ed.removeAllEventListeners('click')).not.toThrow();
    expect(ed._listeners).toBeNull();
  });

  test('handles removal when a type has multiple listeners', () => {
    const ed = new EventDispatcher();
    ed._listeners = {
      multi: [1, 2, 3],
      other: [4]
    };

    ed.removeAllEventListeners('multi');
    const l = ed._listeners;

    // Either the key is removed or its array is emptied
    if (Object.prototype.hasOwnProperty.call(l, 'multi')) {
      expect(Array.isArray(l.multi)).toBe(true);
      expect(l.multi.length).toBe(0);
    } else {
      // Key removed
      expect(l).not.toHaveProperty('multi');
    }

    // Ensure other listeners are unaffected
    expect(l.other).toEqual([4]);
  });
});

