const Vector2D =
  (require('../../../src/math/Vector2D').default) || require('../../../src/math/Vector2D');

describe('Vector2D.multiplyScalar', () => {
  test('multiplies x and y by scalar', () => {
    const v = new Vector2D(2, 3);
    const result = v.multiplyScalar(4);
    expect(result).toBe(v);
    expect(v.x).toBe(8);
    expect(v.y).toBe(12);
  });

  test('returns the same instance for chaining', () => {
    const v = new Vector2D(1, -1);
    const chained = v.multiplyScalar(2).multiplyScalar(0.5);
    expect(chained).toBe(v);
    // 1*2 = 2; 2*0.5 = 1; -1*2 = -2; -2*0.5 = -1
    expect(v.x).toBe(1);
    expect(v.y).toBe(-1);
  });

  test('scaling by zero yields zero vector', () => {
    const v = new Vector2D(5, -7);
    v.multiplyScalar(0);
    expect(v.x).toBe(0);
    expect(v.y).toBeCloseTo(0);
  });

  test('scaling by negative scalar', () => {
    const v = new Vector2D(3, 4);
    v.multiplyScalar(-2);
    expect(v.x).toBe(-6);
    expect(v.y).toBe(-8);
  });

  test('scaling by decimal scalar', () => {
    const v = new Vector2D(1.5, -2.5);
    v.multiplyScalar(2.2);
    expect(v.x).toBeCloseTo(1.5 * 2.2);
    expect(v.y).toBeCloseTo(-2.5 * 2.2);
  });

  test('default constructor initializes to zero', () => {
    const v = new Vector2D();
    expect(v.x).toBe(0);
    expect(v.y).toBe(0);
  });

  test('mutates in place and does not create a new instance', () => {
    const v = new Vector2D(0, 0);
    const before = v;
    v.multiplyScalar(10);
    expect(v).toBe(before);
  });
});

