    expect(particle.dead).toBe(true);
  });

  test('bound crossing reflects particle velocity', () => {
    const line = new LineZoneClass(0, 0, 100, 0);
    line.crossType = 'bound';
    const particle = { p: { x: 50, y: 0 }, v: { x: 2, y: -3 }, radius: 1 };

    line.crossing(particle);

    // Assuming a horizontal line reflection flips the normal component (y)
    expect(particle.v.x).toBe(2);
    expect(particle.v.y).toBe(3);
  });

  test('cross crossing logs error', () => {
    const line = new LineZoneClass(0, 0, 100, 0);
    line.crossType = 'cross';
    const particle = { p: { x: 50, y: 0 }, v: { x: 1, y: 1 }, radius: 1 };

